import subprocess,shutil,hashlib,json,os,tempfile,pathlib
src='products/sites/sqlite-statement-diagnostic/repro/multi_stmt.c'
out='products/services/sqlite-native-delivery'
os.makedirs(out,exist_ok=True)
r={'mission':'SQLITE-NATIVE-DELIVERY','source':src,'source_sha256':hashlib.sha256(open(src,'rb').read()).hexdigest(),'commands':[]}
def run(cmd,cwd=None):
    try:
        p=subprocess.run(cmd,capture_output=True,text=True,timeout=60,cwd=cwd)
        d={'cmd':cmd,'exit':p.returncode,'stdout':p.stdout[-6000:],'stderr':p.stderr[-2000:]}
    except Exception as e:
        d={'cmd':cmd,'exit':None,'error':repr(e)}
    r['commands'].append(d);return d
r['tools']={k:shutil.which(k) for k in ['gcc','cc','clang','tcc','pkg-config']}
r['header']=[p for p in ['/usr/include/sqlite3.h','/usr/local/include/sqlite3.h'] if os.path.exists(p)]
import glob
r['libs']=glob.glob('/usr/lib/*/libsqlite3*')+glob.glob('/usr/lib/libsqlite3*')+glob.glob('/usr/local/lib/libsqlite3*')
cc=r['tools']['gcc'] or r['tools']['cc'] or r['tools']['clang']
r['mounts']=[l for l in open('/proc/mounts').read().splitlines() if any(x in l.split()[1] for x in ['/workspace','/tmp','/dev/shm'])][:10]
if cc:
    for base in ['/workspace/_native', tempfile.gettempdir()+'/_native']:
        try:
            os.makedirs(base,exist_ok=True)
            shutil.copy(src,base+'/multi_stmt.c')
        except Exception as e:
            r['commands'].append({'dir':base,'error':repr(e)});continue
        c=run([cc,'-std=c99','-Wall','-Wextra','-o','ms','multi_stmt.c','-lsqlite3'],cwd=base)
        if c.get('exit')==0:
            e=run(['./ms'],cwd=base)
            if e.get('exit')==0:
                r['native_stdout']=e['stdout'];r['executed_in']=base;break
r['verdict']='NATIVE_EXECUTED' if 'native_stdout' in r else ('COMPILER_ABSENT' if not cc else 'NOT_EXECUTED_SEE_COMMANDS')
open(out+'/result.json','w').write(json.dumps(r,indent=1))
print(json.dumps(r,indent=1)[:7000])
